      this.eventId ||= p.events[0].id; const ev = p.events.find(v => v.id === this.eventId) || p.events[0]; this.eventId = ev.id;
      if (ev.completion_node_id) {
        const node = C.indexProject(p).nodes.get(ev.completion_node_id), done = this.e.state.completed_node_ids.includes(node.id);
        return guide + `<form data-form="event:${escape(ev.id)}"><div class="card row">${button('新建事件规则', 'event-new')}${button('移除阶段事件', 'event-delete', 'class="danger"')}</div><div class="split">${this.list(p.events, 'event', ev.id, '事件规则')}<div class="card"><h2>${escape(ev.title)}</h2><p class="badge">${done ? '已完成' : '待完成'}</p><p>此事件与“${escape(node.title)}”阶段共用完成标准和奖励。完成阶段会同时记入事件记录；从这里确认也会完成对应阶段，只结算一次。</p><h3>完成标准</h3><pre>${escape(node.completion_criteria || '手动确认本阶段完成')}</pre><h3>不算完成的情况</h3><pre>${escape(node.completion_exclusions.join('\n') || '未设置')}</pre><h3>完成后的变化</h3><pre>${escape(node.effects.length ? json(node.effects) : '只记录阶段与事件完成，无额外奖励')}</pre><div class="row">${button('编辑对应剧情阶段', 'event-node-edit', `data-id="${escape(node.id)}"`)}${button(done ? '本阶段已完成' : '手动确认本阶段完成', 'event-manual', done ? 'disabled' : '')}${button('查看完成记录', 'event-records')}</div><p class="muted">完整剧本和分支出口在剧本页编辑；输入栏行动仍由玩家发送后推进。</p></div></div></form>`;
      }
      let effects = ev.effects; try { if (this.forms['event:' + ev.id]?.effects) effects = C.parseJSON(this.forms['event:' + ev.id].effects); } catch {}
      const changes = Array.isArray(effects) ? effects.map(effect => {
        if (!C.object(effect)) return '请检查效果 JSON';
        if (effect.collect) return '记录收集项：' + (p.collections.find(c => c.id === effect.collect)?.title || effect.collect);
        const value = effect.add || effect.set; if (!value) return '请检查效果 JSON';
        const name = p.variables.find(v => v.id === value.variable)?.title || value.variable;
        return name + (effect.add ? ' ' + (value.value >= 0 ? '+' : '') + value.value : ' 设置为 ' + value.value) + (value.max != null ? '（此行为最多加到 ' + value.max + '）' : '') + (value.min != null ? '（此行为最低减到 ' + value.min + '）' : '');
      }).join('；') : '变化草稿尚未通过校验';
      return guide + `<form data-form="event:${escape(ev.id)}"><div class="card row">${button('新建事件规则', 'event-new')}${button(ev.repeat_policy === 'once' && this.e.state.event_counts[ev.id] ? '本规则已确认发生' : '手动确认发生并应用变化', 'event-manual', ev.repeat_policy === 'once' && this.e.state.event_counts[ev.id] ? 'disabled' : '')}${button('删除规则', 'event-delete', 'class="danger"')}<span class="muted">手动确认直接执行本条规则，不调用模型。</span></div><div class="split">${this.list(p.events, 'event', ev.id, '事件规则')}<div class="card"><h2>编辑事件规则</h2>${input('规则名称', 'title', ev.title)}${area('需要识别的行为或结果', 'description', ev.description, 4)}${area('什么情况下算已经发生', 'completion_criteria', ev.completion_criteria, 4)}${area('不算发生的情况（每行一条）', 'exclusions', ev.exclusions.join('\n'), 3)}<div class="grid">${select('如何确认发生', 'detection', [['api', '辅助 API 分析正文'], ['manual', '仅手动确认']], ev.detection)}${select('同一规则可以执行几次', 'repeat_policy', [['once', '整个剧本一次'], ['once_per_accepted_turn', '每轮实际发生可重复，同一回复一次']], ev.repeat_policy)}</div>${input('最多实际发生次数（可空；可重复事件的总次数上限）', 'max_occurrences', ev.max_occurrences ?? '', 'number', 'min="1"')}${checkbox('启用此规则', 'enabled', ev.enabled)}${checkbox('核验通过后自动应用变化', 'auto_settle', ev.auto_settle)}${select('结果核验级别','verification',[['ordinary','普通：主模型报告后本地结算'],['critical','关键：集中复核后结算']],ev.verification || 'ordinary')}<p class="muted">用于解锁的结果、数值门槛及物品取得会自动按关键结果处理，不能通过选择普通绕过。</p><h3>发生后的变化</h3><p class="event-effects-summary">${escape(changes || '尚未配置变化，请从下面添加。')}</p><div class="grid">${input('要记录的收集项编号（可空）', 'collect_id', '')}${select('要增加的变量', 'effect_variable', [['', '不选择'], ...p.variables.filter(v => v.type === 'number').map(v => [v.id, v.title || v.id])], '')}${input('变化量（减分可填负数）', 'effect_delta', 1, 'number')}${select('变化方式', 'effect_operation', [['add', '增加 / 减少'], ['set', '设置为指定值']], 'add')}${input('此行为最多加到（可空）', 'reward_max', '', 'number')}${input('此行为最低减到（可空）', 'reward_min', '', 'number')}</div>${button('加入发生后的变化', 'append-effect')}<p class="muted">先填写并加入变化，再保存规则。数值可在“数据 → 数值载体”创建、查看归属和当前值；此行为的限制独立于载体总上限。收集记录可作为分支的解锁条件。</p><details><summary>高级：效果 JSON</summary>${area('完成效果 JSON', 'effects', json(ev.effects), 5)}</details><details><summary>高级：适用范围、前置条件与身份</summary>${input('主体 ID（可空；玩家可写 player）', 'actor_id', ev.actor_id || '')}${input('对象 ID（可空）', 'recipient_id', ev.recipient_id || '')}${input('适用节点 ID（逗号分隔；留空表示整个剧本）', 'scope_nodes', ev.scope.kind === 'nodes' ? ev.scope.node_ids.join(',') : '')}${this.conditionHelper('event')}${area('事件前置条件 JSON', 'condition', json(ev.condition ?? true), 4)}<p>稳定事件 ID：<code>${escape(ev.id)}</code></p></details><div class="actions">${button('保存事件规则', 'event-save', 'class="primary"')}${button('查看识别记录', 'event-records')}</div></div></div></form>`;
    }
    analysisEstimate(text) {
      const length=String(text ?? this.forms.analysis?.analysis_text ?? this.e.project.original_text ?? '').length;
      const chunks=Math.max(1,Math.ceil(length/(this.e.settings.profile.analysis_chunk_chars || 3000)));
      return this.e.analysisProgress?.total || (this.e.settings.profile.auto_partition ? 1 : 0)+chunks*(this.e.settings.profile.author_review ? 2 : 1)+(chunks>1 ? 1 : 0)+(this.e.settings.profile.author_review ? 1 : 0);
    }
    companionRecords() {
      const q=this.e.state.companion;if(!q)return '';
      return `<div class="card"><h2>阶段核验与异常记录</h2><p>待核验 ${q.queue.length} 项；关键结果未确认时不开放依赖入口。</p>${q.queue.map(x=>`<p>${escape(x.id)} · ${escape(x.status)} · 回复 ${Number(x.source.assistant_id)+1}${x.status==='verified' ? button('作者确认结算','companion-settle',`data-key="${escape(x.key)}"`) : ''}</p>`).join('')}${button('重新集中核验','companion-retry',this.e.busy ? 'disabled' : '')}<details><summary>后台诊断（最近100条）</summary>${q.logs.slice().reverse().map(x=>`<p>${escape(x.kind)}：${escape(x.message)}</p>`).join('')}</details></div>`;
    }
    recordsPage() {
      const subnav = `<div class="subnav">${button('进度记录', 'records-tab', `data-tab="progress" class="${this.recordsTab === 'progress' ? 'active' : ''}"`)}${button('完成与解锁关系', 'records-tab', `data-tab="graph" class="${this.recordsTab === 'graph' ? 'active' : ''}"`)}</div>`;
      if (this.recordsTab === 'graph') return subnav + this.graphPage();
      const e = this.e; const p = e.project; const s = e.state; const refs = C.indexProject(p);
      const statuses = {completed: '已发生，待结算', uncertain: '不确定', proposed: '仅提议', rejected: '被拒绝', not_occurred: '未发生'};
      return subnav + `<div class="card"><h2>当前阶段进展</h2><p>${escape(e.flowNotice || '等待行动与回复')}</p>${s.turn_context?.label ? `<p>已选择：${escape(s.turn_context.label)} · 玩家消息 ${Number(s.turn_context.user_id) + 1}</p>` : ''}${s.stage_progress ? `<p>${escape(s.stage_progress.summary || '暂无可确认的新事实')}</p><p class="muted">${escape(s.stage_progress.missing.join('；'))}</p>` : '<p class="muted">阶段完成后仅保留结果标记，工作摘要不继续累计。</p>'}<p>已确认结果：${s.collected_ids.map(x => `<code>${escape(x)}</code>`).join('、') || '暂无'}</p></div>${p.packages.some(b => s.package_progress?.[b.id]?.started) ? `<div class="card"><h2>事件包进度</h2>${p.packages.filter(b => s.package_progress?.[b.id]?.started).map(b => { const q = s.package_progress[b.id]; return `<div class="kv"><span>${escape(b.title)} · ${escape(refs.nodes.get(q.current_node_id)?.title || q.current_node_id)}<br><small>${escape(q.stage_progress?.summary || '暂无工作摘要')}</small></span><strong>${escape(({running: '进行中', done: '已完成', waiting: '等待条件', disabled: '已关闭'})[q.status] || q.status)}</strong></div>`; }).join('')}</div>` : ''}<div class="card"><h2>进度记录</h2><div class="grid"><div><h3>已完成节点</h3>${s.completed_node_ids.map(k => `<p>${escape(refs.nodes.get(k)?.title || k)}</p>`).join('') || '<p class="empty">暂无</p>'}</div><div><h3>事件累计</h3>${Object.entries(s.event_counts).map(([k, v]) => `<div class="kv"><span>${escape(refs.events.get(k)?.title || k)}</span><strong>${v}</strong></div>`).join('') || '<p class="empty">暂无</p>'}</div></div></div>
      ${this.completionRecords()}${this.companionRecords()}<div class="card"><h2>待确认与失败检查</h2>${e.busy ? '<span class="badge">辅助任务运行中</span>' : ''}${s.pending_checks.map(check => `<div class="card"><h3>回复楼层 ${Number(check.assistant_id) + 1} · ${escape(check.status)}</h3>${check.error ? `<p class="warn">${escape(check.error)}</p>` : ''}${['error', 'stale', 'partial'].includes(check.status) ? button(check.status === 'partial' ? '继续检查未查候选' : '重新检查', 'retry', `data-key="${escape(check.key)}"`) : ''}${check.results.filter(r => !r.handled).map(r => `<div class="card"><strong>${escape(refs.events.get(r.event_id)?.title || r.event_id)}</strong> <span class="badge">${escape(statuses[r.status])}</span>${r.evidence.map(x => `<p class="muted">“${escape(x.quote)}”</p>`).join('')}${r.note ? `<p class="warn">${escape(r.note)}</p>` : ''}${['completed', 'uncertain'].includes(r.status) ? `<div class="row">${button('确认发生并结算', 'result-accept', `data-key="${escape(check.key)}" data-id="${escape(r.event_id)}"`)}${button('忽略', 'result-dismiss', `data-key="${escape(check.key)}" data-id="${escape(r.event_id)}"`)}</div>` : ''}</div>`).join('')}</div>`).join('') || '<p class="empty">没有待处理的检查</p>'}</div>
      <div class="card"><h2>近期操作（最多 25 条）</h2>${s.history.slice().reverse().map(tx => `<p>${escape(tx.label)} <span class="muted">${new Date(tx.at).toLocaleString()}</span></p>`).join('') || '<p class="empty">暂无操作</p>'}${button('回退最近一次', 'undo', s.history.length ? '' : 'disabled')}</div>`;
