    analysisPage() {
      const e = this.e, draft = e.analysisDraft, p = draft?.project || e.project, a = p.analysis, refs = C.indexProject(p), progress = e.analysisProgress;
      const reply = e.rawAnalysis?.replies.find(x => x.id === this.forms.analysis?.analysis_saved_id);
      const replyName = x => x.kind === 'repair' ? (x.repair_type === 'variables' ? '变量依据补修' : x.repair_type==='evidence' ? '分散证据补修' : '节点来源补修') : ({full:'正式分析',chunk:'分段分析',merge:'跨段整合',plan:'分段规划',review_chunk:'分段独立复核',review_script:'转化结果复核'}[x.kind] || x.kind);
      const repairInfo = reply?.kind === 'repair' ? `<p class="muted">这份是${escape(replyName(reply))}回复，只包含补修字段；完整规则仍在原始分析记录中，恢复时由程序合并。</p><details class="repair-variables"><summary>补修前的变量定义（供排查）</summary><pre>${escape(json(reply.sourceResult?.variables || []))}</pre></details>` : '';
