      const proposed = item => item.suggested ? '<span class="badge">补充构想</span>' : '';
      const count = draft ? {nodes: p.nodes.length, routes: p.nodes.reduce((n, x) => n + x.routes.length, 0), packages: p.packages.length, events: p.events.length + p.nodes.filter(n => !n.suggested && n.completion_criteria.trim() && !p.events.some(x => x.completion_node_id === n.id)).length} : null;
      const prompts = e.defaultPrompts();
      const promptEditor = `<details class="analysis-prompts"><summary>查看与修改分析提示词</summary><p class="muted">这里与 API 页共用已保存的系统提示词。修改后点击保存，再发起分析；保留 JSON 字段与证据约定。</p>${area('分析系统提示词（system）', 'analysis_prompt', e.settings.profile.analysis_prompt || prompts.analysis, 12)}${area('跨段合并系统提示词（system）', 'analysis_merge_prompt', e.settings.profile.analysis_merge_prompt || prompts.merge, 10)}${area('分段规划提示词','partition_prompt',e.settings.profile.partition_prompt || prompts.partition,5)}${area('分段独立复核提示词','review_prompt',e.settings.profile.review_prompt || prompts.review,6)}${area('转化后复核提示词','review_script_prompt',e.settings.profile.review_script_prompt || prompts.review_script,6)}${area('分散证据补修提示词','repair_evidence_prompt',e.settings.profile.repair_evidence_prompt || prompts.repair_evidence,5)}${area('节点来源补修提示词','repair_source_prompt',e.settings.profile.repair_source_prompt || prompts.repair_source,5)}${area('变量依据补修提示词','repair_variables_prompt',e.settings.profile.repair_variables_prompt || prompts.repair_variables,5)}<div class="row">${button('保存分析提示词', 'analysis-prompts-save', e.busy ? 'disabled' : '')}${button('恢复默认分析提示词', 'analysis-prompts-reset', e.busy ? 'disabled' : '')}${button('预览当前输入与已保存提示词', 'analysis-preview')}</div>${this.analysisPreview ? `<p class="muted">发送前预览：使用已保存的提示词和当前原文、要求。实际分析先规划分段；此处为分析正文模板预览，各次规划、分段和整合的真实请求见下方记录。</p><pre class="prompt-preview">${escape(json(this.analysisPreview))}</pre>` : ''}<h3>最近一次整理 / 分析的已发请求</h3>${(e.rawAnalysis?.requests || []).map((r, i) => `<details><summary>请求 ${i + 1} · ${escape(r.kind)}${r.part ? ' · ' + r.part + '/' + r.parts : ''}</summary>${r.storage_truncated ? '<p class="warn">本地保留预算已满，此展示不完整。</p>' : ''}<pre class="sent-prompt">${escape(r.text)}</pre></details>`).join('') || '<p class="empty">尚无已发送请求记录</p>'}</details>`;
      const conversion = draft ? `<div class="card analysis-conversion"><h2>分析完成，转化为可用内容</h2><p>${count.nodes} 个剧情阶段 · ${count.events} 条事件规则 · ${count.routes} 个分支出口 · ${count.packages} 个剧情事件包</p><p>转化后，阶段和分支在“剧本”页，完成规则在“事件”页，条件关系在“记录”页。有完成标准的阶段会登记对应事件，共用一次结算；未明确的标准留待编辑。</p>${draft.is_partial ? '<p class="warn">这只是单个分块，尚未完成全篇整合。</p>' : ''}<div class="row">${button('转化为剧本、事件与分支', 'analysis-convert', e.busy ? 'disabled' : 'class="primary"')}${button('备份当前进度', 'export-progress')}${button('导出分析草稿', 'analysis-export')}${button('复核当前草稿及转化结果','analysis-review',e.busy ? 'disabled' : '')}</div><p class="muted">转化无需再次调用 API。当前剧本保留在草稿或世界书，转换后的剧本先关闭注入，核对后启用。</p></div>` : '';
